from pathlib import Path
import os,resource,signal,json,hashlib
resource.setrlimit(resource.RLIMIT_CPU,(30,30));resource.setrlimit(resource.RLIMIT_AS,(536870912,536870912));signal.alarm(40);p=Path(__file__).parent;os.environ['MPLCONFIGDIR']=str(p/'mpl-local-cache')
