import matplotlib.pyplot as plt
A=json.loads((p/'assessment.json').read_text())['points'];F=json.loads((p/'friction.json').read_text())['joint1_force_series'];t=[1000*z['elapsed'] for z in A];plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.grid':True,'grid.alpha':.2,'axes.spines.right':False,'axes.spines.top':False});fig,ax=plt.subplots(1,2,figsize=(13,5.5),constrained_layout=True)
