fig.text(.5,-.025,'Prediction diagnostics only. One actual commit preceded this refusal; the failed candidate was not executed. Branch co-occurrence does not certify nonlinear accuracy.',ha='center',fontsize=9);fig.savefig(p/'candidate_branch_affine_refusal40.png',dpi=160,bbox_inches='tight');plt.close(fig)
